// pt_BR.yaml rule pt_BR.accentParonyms def verbFinding
export function verbFinding(
  ctx: DetectContext,
  start: number,
  end: number,
  typed: string,
  context: RawFinding["context"],
): RawFinding | null {
  const verb = ptVerbTwin(typed.toLowerCase());
  if (!(verb !== undefined && !ctx.dictionary.has(typed.toLowerCase()))) return null;
  return {
    ruleId: "portugueseAccentParonyms",
    messageKey: "review_msg_pt_accent_verb",
    range: { start, end },
    alternatives: [applyWordCase(verb, detectWordCase(typed))],
    context,
  };
}

// pt_BR.yaml rule pt_BR.accentParonyms def afterLead
export function afterLead(m: RegExpExecArray, ctx: DetectContext): RawFinding | null {
  const typed = m.groups!.target;
  const alternatives =
    ptAccentedTwins(typed) ??
    (NCA_NOUN.test(typed) ? [typed.replace(/cia(s?)$/, "ça$1")] : undefined);
  if (!(alternatives !== undefined && !ctx.dictionary.has(typed))) return null;
  const span = m.indices!.groups!.target;
  if (gluedAfter(ctx.text, span[1])) return null;
  if (/^um/i.test(m.groups!.lead) && RECIPROCAL.test(ctx.text.slice(span[1], span[1] + 96)))
    return null;
  return {
    ruleId: "portugueseAccentParonyms",
    messageKey: "review_msg_pt_accent_paronym",
    range: { start: span[0], end: span[1] },
    alternatives,
    context: { start: m.index, end: span[1] },
    ...(alternatives.length > 1 ? { requiresChoice: true as const } : {}),
  };
}

// pt_BR.yaml rule pt_BR.confusions def CLAUSE_START
export const CLAUSE_START = /(?:^|[.!?:;][ \t\r\n\u00a0"”»)]{0,8}|\n[ \t\u00a0]{0,8})$/;

// pt_BR.yaml rule pt_BR.confusions def crase
export function crase(
  ctx: DetectContext,
  m: RegExpExecArray,
  alternatives: string[],
): RawFinding | null {
  const span = m.indices!.groups!.target;
  const typed = ctx.text.slice(span[0], span[1]);
  if (ctx.dictionary.has(typed.toLowerCase())) return null;
  return {
    ruleId: "portugueseConfusions",
    messageKey: "review_msg_pt_crase",
    range: { start: span[0], end: span[1] },
    alternatives: alternatives.map((alt) => applyWordCase(alt, detectWordCase(typed))),
    context: { start: m.index, end: Math.max(span[1], m.index + m[0].length) },
    ...(alternatives.length > 1 ? { requiresChoice: true as const } : {}),
  };
}

// pt_BR.yaml rule pt_BR.contractions def INFINITIVE_FORM
export const INFINITIVE_FORM =
  /^(?:\p{L}+(?:ar|er|ir|ares|eres|ires|armos|ermos|irmos|arem|erem|irem)|\p{L}*p[oô]r|\p{L}*por(?:es|mos|em)|\p{L}+(?:ar|er|ir)-(?:me|te|se|lhes?|nos|vos)|\p{L}+[áêíô]-[ln][oa]s?)$/u;

// pt_BR.yaml rule pt_BR.contractions def CLAUSE_AHEAD
export const CLAUSE_AHEAD = /^[^.;:!?()\n]{0,80}/;

// pt_BR.yaml rule pt_BR.contractions def PT_MODAL_BEFORE
export const PT_MODAL_BEFORE =
  /(?<![\p{L}])(?:pode|posso|podemos|podem|podia|quero|queremos|quer|queria|deve|devemos|devem|deveria|preciso|precisamos|precisa|precisam|para|sem|que|de|há|hei)[ \t\u00a0]+$/iu;

// pt_BR.yaml rule pt_BR.contractions def CONTRACTION_START
export const CONTRACTION_START = /(?:^|[.!?:;]["”»)]?[ \t\u00a0]*|\n[ \t\u00a0]*)$/;

// pt_BR.yaml rule pt_BR.contractions def infinitiveAhead
export function infinitiveAhead(text: string) {
  return (CLAUSE_AHEAD.exec(text)![0].match(/[\p{L}\p{M}-]+/gu) ?? []).some(
    (word, index, words) =>
      INFINITIVE_FORM.test(word) &&
      (!NOUN_R.has(word.toLowerCase()) ||
        (VERB_LATER.has(word.toLowerCase()) && (index > 0 || words.length === 1))),
  );
}

// pt_BR.yaml rule pt_BR.typographyStyleFrames def ROMAN
export const ROMAN = [
  [90, "XC"],
  [50, "L"],
  [40, "XL"],
  [10, "X"],
  [9, "IX"],
  [5, "V"],
  [4, "IV"],
  [1, "I"],
] as [number, string][];

// pt_BR.yaml rule pt_BR.typographyStyleFrames def roman
export function roman(n: number): string {
  const next = ROMAN.find((pair) => n >= pair[0]);
  if (!(next !== undefined)) return "";
  return next[1] + roman(n - next[0]);
}

