// pt_BR.yaml rule pt_BR.cliticPlacement def NON_FINITE
export const NON_FINITE = /(?:[aeioô]r|[aeio]rem|[aeio]rmos|[aeio]res|ndo)$/;

// pt_BR.yaml rule pt_BR.cliticPlacement def plainObject
export function plainObject(pronoun: string) {
  return pronoun === "nos" ? pronoun : pronoun.replace(/^[ln](?=[oa]s?$)/, "");
}

// pt_BR.yaml rule pt_BR.cliticPlacement def finiteVerb
export function finiteVerb(verb: string, pronoun: string): string | null {
  return NON_FINITE.test(verb) && !(/[aeio]r(?:em|es)$/.test(verb) && ptRStem(verb.slice(0, -2)))
    ? null
    : verb.endsWith("mo") && (pronoun === "nos" || /^l[oa]s?$/.test(pronoun))
      ? `${verb}s`
      : /^l[oa]s?$/.test(pronoun)
        ? null
        : /^n[oa]s?$/.test(pronoun) && pronoun !== "nos"
          ? /(?:ão|õe|[aeê]m)$/.test(verb)
            ? verb
            : null
          : /^[oa]s?$/.test(pronoun)
            ? /[aeiouáéíóúâêô]$/.test(verb)
              ? verb
              : null
            : verb;
}

// pt_BR.yaml rule pt_BR.cliticPlacement def withoutConsonant
export function withoutConsonant(verb: string) {
  return /s$/.test(verb)
    ? verb.slice(0, -1)
    : verb
        .slice(0, -1)
        .replace(/[aeo]$/, (vowel) => STRESSED[vowel])
        .replace(/^p[oô]$/, "pô");
}

// pt_BR.yaml rule pt_BR.cliticPlacement def cliticFinding
export function cliticFinding(
  ctx: DetectContext,
  m: RegExpExecArray,
  replacement: string,
  messageKey: RawFinding["messageKey"],
): RawFinding | null {
  const typed = m.groups!.target;
  if (ctx.dictionary.has(typed.toLowerCase())) return null;
  const span = m.indices!.groups!.target;
  return {
    ruleId: "portugueseCliticPlacement",
    messageKey,
    range: { start: span[0], end: span[1] },
    alternatives: [applyWordCase(replacement, detectWordCase(typed))],
    context: { start: m.index, end: span[1] },
  };
}

// pt_BR.yaml rule pt_BR.ao90 def SMALL_WORDS
export const SMALL_WORDS = /^(?:que|em|de|do|da|dos|das|e|o|a|os|as|no|na|com|para|por|se|um|uma)$/;

// pt_BR.yaml rule pt_BR.ao90 def NAMED_PLACE
export const NAMED_PLACE =
  /(?<![\p{L}])(?:Rua|Avenida|Av\.|Praça|Largo|Travessa|Estrada|Rodovia|Ponte|Estádio|Escola|Colégio|Parque|Vila|Bairro|Jardim|Hospital|Revolução)[ \t\u00a0]+(?:\d{1,2}|\p{Lu}\p{Ll}+)[ \t\u00a0]+de[ \t\u00a0]+$/u;

// pt_BR.yaml rule pt_BR.ao90 def joinPrefix
export function joinPrefix(prefix: string, word: string) {
  return prefix === "co"
    ? `co${word[0] === "h" ? word.slice(1) : word}`
    : word[0] === "h" || PREFIXES[prefix].includes(word[0])
      ? `${prefix}-${word}`
      : /[aeiou]$/.test(prefix) && /^[rs]/.test(word)
        ? `${prefix}${word[0]}${word}`
        : `${prefix}${word}`;
}

// pt_BR.yaml rule pt_BR.ao90 def ao90Finding
export function ao90Finding(ctx: DetectContext, start: number, end: number, replacement: string) {
  if (ctx.dictionary.has(ctx.text.slice(start, end).toLowerCase())) return null;
  return finding("portugueseAO90", "review_msg_pt_ao90", start, end, [replacement]);
}

// pt_BR.yaml rule pt_BR.invalidDates def MONTH_NAMES
export const MONTH_NAMES =
  "janeiro fevereiro março abril maio junho julho agosto setembro outubro novembro dezembro".split(
    " ",
  );

// pt_BR.yaml rule pt_BR.invalidDates def WEEKDAY_NAMES
export const WEEKDAY_NAMES = "domingo segunda terça quarta quinta sexta sábado".split(" ");

// pt_BR.yaml rule pt_BR.invalidDates def DATE_CUE
export const DATE_CUE =
  /(?:^|[\s(])(?:em|desde|até|dia|data|prazo|vence)(?:[ \t]+(?:é|era|foi|será))?[ \t]*:?[ \t]{1,8}$/iu;

// pt_BR.yaml rule pt_BR.invalidDates def monthOf
export function monthOf(name: string) {
  return MONTH_NAMES.findIndex((month) => month.startsWith(name.toLowerCase())) + 1;
}

// pt_BR.yaml rule pt_BR.invalidDates def dateExists
export function dateExists(day: number, month: number, year?: number) {
  return month >= 1 && month <= 12 && day >= 1 && day <= daysInMonth(month, year);
}

// pt_BR.yaml rule pt_BR.invalidDates def invalidDate
export function invalidDate(m: RegExpExecArray): RawFinding {
  return {
    ruleId: "portugueseDates",
    messageKey: "review_msg_pt_invalid_date",
    range: { start: m.index, end: m.index + m[0].length },
    alternatives: [],
    warningOnly: true,
  };
}

// pt_BR.yaml rule pt_BR.invalidDates def weekdayLike
export function weekdayLike(typed: string, full: string) {
  return /^\p{Lu}/u.test(typed) ? full[0].toUpperCase() + full.slice(1) : full;
}

// pt_BR.yaml rule pt_BR.invalidDates def wrongWeekday
export function wrongWeekday(
  ctx: DetectContext,
  m: RegExpExecArray,
  month: number,
  dayGroup: string,
): RawFinding | null {
  const weekday = m.groups!.weekday;
  const year = m.groups!.year as string | undefined;
  const day = Number(m.groups![dayGroup]);
  if (!dateExists(day, month, year === undefined ? undefined : Number(year))) return null;
  const years =
    year === undefined
      ? yearsFor(month, day, contextYear(ctx.text, m.index, ctx.lang))
      : [Number(year)];
  const weekdays = [...new Set(years.map((one) => weekdayOf(one, month, day)))];
  const typed = WEEKDAY_NAMES.findIndex((name) =>
    name.startsWith(weekday.toLowerCase().slice(0, 3)),
  );
  if (!years.length || weekdays.includes(typed)) return null;
  const text = m[0];
  const alternatives = weekdays.map(
    (actual) =>
      `${weekdayLike(weekday, WEEKDAY_NAMES[actual] + (actual % 6 === 0 ? "" : "-feira"))}${text.slice(weekday.length)}`,
  );
  const shifted = nearestDayOn(years[0], month, day, typed);
  const dayAt = m.indices!.groups![dayGroup].map((at) => at - m.index);
  return {
    ruleId: "portugueseDates",
    messageKey: year === undefined ? "review_msg_weekday_no_year" : "review_msg_pt_weekday_date",
    range: { start: m.index, end: m.index + text.length },
    alternatives:
      shifted !== null
        ? [...alternatives, `${text.slice(0, dayAt[0])}${shifted}${text.slice(dayAt[1])}`]
        : alternatives,
    requiresChoice: true,
  };
}

// pt_BR.yaml rule pt_BR.commas def NO_COMMA_BEFORE
export const NO_COMMA_BEFORE =
  /^(?:e|mas|ou|nem|que|pois|porém|se|quando|como|onde|porque|então|logo|assim|também)$/iu;

// pt_BR.yaml rule pt_BR.commas def MAS_NO_COMMA
export const MAS_NO_COMMA = /^(?:e|ou|nem|não|só|somente|apenas|mas|que|porém)$/iu;

// pt_BR.yaml rule pt_BR.commas def commaAt
export function commaAt(m: RegExpExecArray, fixed: string) {
  const span = m.indices!.groups!.target;
  return finding("portugueseCommas", "review_msg_pt_comma", span[0], span[1], [fixed], {
    context: { start: m.index, end: Math.max(span[1], m.index + m[0].length) },
  });
}

// pt_BR.yaml rule pt_BR.commas def direct
export function direct(rest: string) {
  const words = rest.toLowerCase().match(/\p{L}+/gu) ?? [];
  return (
    !words.some((word) => STATEMENT_VERB.has(word)) &&
    !words.some((word, index) => index > 0 && SUBJECTS.has(word))
  );
}

// pt_BR.yaml rule pt_BR.agreement def AGREE_SUBJECT_BEFORE
export const AGREE_SUBJECT_BEFORE =
  /(?<![\p{L}])(?:eu|tu|ele|ela|você|nós|eles|elas|vocês|que|quem|o|a|isso|isto|tudo|nada|algo|ninguém)[ \t\u00a0]+$/iu;

// pt_BR.yaml rule pt_BR.agreement def SUBJECTLESS
export const SUBJECTLESS =
  /(?:^|[.!?;:,\n]["'”’»)]*[ \t\u00a0]*|(?:^|[^\p{L}])(?:já|ontem|hoje|então|ainda|agora|aí|enfim|finalmente|não)[ \t\u00a0]+)$/iu;

// pt_BR.yaml rule pt_BR.agreement def ARRIVE_OR_LACK
export const ARRIVE_OR_LACK = /^(?:\p{L}+[ \t\u00a0]+(?:\p{L}+[ \t\u00a0]+)?)?(?:cheg|falt)/iu;

// pt_BR.yaml rule pt_BR.agreement def PLURAL_DETERMINER_WORD
export const PLURAL_DETERMINER_WORD =
  /^(?:mais|muitos|muitas|vários|várias|alguns|algumas|poucos|poucas|diversos|diversas|inúmeros|inúmeras|tantos|tantas|uns|umas|os|as|dois|duas|três|quatro|cinco|seis|sete|oito|nove|dez|vinte|cem|[2-9]|\d{2,})$/;

// pt_BR.yaml rule pt_BR.agreement def QUESTION_LEAD
export const QUESTION_LEAD =
  /^(?:sei|sabe|sabem|sabemos|saber|sabia|soube|decidir|decide|decidiu|decidimos|escolher|escolhe|escolheu|perguntar|pergunta|perguntou|ensinar|ensina|ensinou|aprender|aprende|aprendeu|entender|entende|explicar|explica|explicou|dizer|diz|disse|mostrar|mostra|mostrou|indicar|indica|definir|define|planejar|ideia|dúvida|noção|até|desde|de|para|sobre|é|era)$/iu;

// pt_BR.yaml rule pt_BR.agreement def ELAPSED
export const ELAPSED =
  /^[ \t\u00a0]{1,8}(?:\p{L}+[ \t\u00a0]{1,8})?(?:vezes|anos|meses|semanas|dias|horas|minutos|segundos|tempos|décadas|séculos|instantes|momentos|tempo)(?![\p{L}\p{M}\p{N}_'’@/#\\-])/iu;

// pt_BR.yaml rule pt_BR.agreement def subjectless
export function subjectless(ctx: DetectContext, m: RegExpExecArray) {
  return (
    !ARRIVE_OR_LACK.test(ctx.text.slice(m.index, m.index + 40)) ||
    SUBJECTLESS.test(ctx.text.slice(Math.max(0, m.index - 16), m.index))
  );
}

// pt_BR.yaml rule pt_BR.agreement def agreementFinding
export function agreementFinding(
  ctx: DetectContext,
  m: RegExpExecArray,
  replacement: string,
  messageKey: RawFinding["messageKey"],
): RawFinding | null {
  const typed = m.groups!.target;
  if (ctx.dictionary.has(typed.toLowerCase())) return null;
  const span = m.indices!.groups!.target;
  return {
    ruleId: "portugueseAgreement",
    messageKey,
    range: { start: span[0], end: span[1] },
    alternatives: [applyWordCase(replacement, detectWordCase(typed))],
    context: { start: m.index, end: Math.max(span[1], m.index + m[0].length) },
  };
}

// pt_BR.yaml rule pt_BR.agreement def postposed
export function postposed(
  ctx: DetectContext,
  m: RegExpExecArray,
  table: Readonly<Record<string, string>>,
) {
  if (AGREE_SUBJECT_BEFORE.test(ctx.text.slice(Math.max(0, m.index - 16), m.index))) return null;
  if (!subjectless(ctx, m)) return null;
  return agreementFinding(ctx, m, table[m.groups!.target.toLowerCase()], "review_msg_pt_agreement");
}

// pt_BR.yaml rule pt_BR.agreement def bareSubject
export function bareSubject(
  ctx: DetectContext,
  m: RegExpExecArray,
  table: Readonly<Record<string, string>>,
) {
  const noun = m.groups!.noun;
  if (noun !== noun.toLowerCase() || /mos$/.test(noun) || TIME_WORD.test(noun)) return null;
  if (PLURAL_DETERMINER_WORD.test(noun)) return null;
  const info = ptNoun(noun);
  if (!(info?.plural === true && info.feminine !== null)) return null;
  if (AGREE_SUBJECT_BEFORE.test(ctx.text.slice(Math.max(0, m.index - 16), m.index))) return null;
  if (!subjectless(ctx, m)) return null;
  return agreementFinding(ctx, m, table[m.groups!.target.toLowerCase()], "review_msg_pt_agreement");
}

