    if (PARONYM_PREPOSITION_BEFORE.test(ctx.text.slice(Math.max(0, m.index - 12), m.index)))
      return null;
    const span = m.indices!.groups!.target;
    if (!PT_OBJECT_AFTER.test(ctx.text.slice(span[1], span[1] + 12))) return null;
